+package jaegerstorage
+
+// returns the cached factory for name, creating and caching it under factoryMu on first request
+func (s *storageExt) lookupOrCreateTraceFactory(name string) (tracestore.Factory, error) {
+	s.factoryMu.Lock()
+	defer s.factoryMu.Unlock()
+	if f, ok := s.traceFactories[name]; ok {
+		return f, nil
+	}
+	cfg, ok := s.cfg.TraceBackends[name]
+	if !ok {
+		return nil, fmt.Errorf("storage %q not declared", name)
+	}
+	f, err := storageconfig.CreateTraceStorageFactory(cfg)
+	if err != nil {
+		return nil, err
+	}
+	s.traceFactories[name] = f
+	return f, nil
+}

